INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/anansi#specialite:cemies', 'classes/anansi', 2, 'CEMIES', 'cemies', 'Description Cemies', NULL, 'classes', 'Classe Maverick V7 › Anansi › X17:AJ19, AM31:BA31', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/anansi#specialite:marionnettiste', 'classes/anansi', 1, 'MARIONNETTISTE', 'marionnettiste', 'Description Marionnettiste', NULL, 'classes', 'Classe Maverick V7 › Anansi › A17:M19, AM17:BA17', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/arbaletrier#specialite:baliste', 'classes/arbaletrier', 2, 'BALISTE', 'baliste', NULL, NULL, 'classes', 'Classe Maverick V7 › Arbalètrier › X17:AJ19', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/arbaletrier#specialite:grand-arbaletrier', 'classes/arbaletrier', 1, 'GRAND ARBALÉTRIER', 'grand-arbaletrier', NULL, NULL, 'classes', 'Classe Maverick V7 › Arbalètrier › A17:M19', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/archer#specialite:grand-archer', 'classes/archer', 2, 'GRAND ARCHER', 'grand-archer', 'Description Grand Archer', NULL, 'classes', 'Classe Maverick V7 › Archer › X17:AJ19, AL31:AZ31', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/archer#specialite:tireur-delite', 'classes/archer', 1, 'TIREUR D''ÉLITE', 'tireur-delite', 'Description Tireur d''élite', 'Le Tireur d''élite est le combattant qui maîtrise très bien l''arc, capable d’infliger des dégâts dévastateurs avec une précision chirurgicale. Son expérience lui permet de tirer plus loin, parfois avec une force suffisante pour percer les armures les plus robustes.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/archimage#specialite:elementaliste', 'classes/archimage', 1, 'Élémentaliste', 'elementaliste', NULL, NULL, 'classes', 'Classe Maverick V7 › Archimage › J18:P23', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/archimage#specialite:occultiste', 'classes/archimage', 2, 'Occultiste', 'occultiste', NULL, NULL, 'classes', 'Classe Maverick V7 › Archimage › U18:AA23', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/barde#specialite:danseur', 'classes/barde', 1, 'DANSEUR', 'danseur', 'Description Danseur', 'Le Danseur virevolte sur le champ de bataille, alliant grâce et danger en une performance létale. Ses mouvements lui permettent d’éviter les attaques et de frapper là où l’ennemi s’y attendrait le moins.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/barde#specialite:menestrel', 'classes/barde', 2, 'MÉNESTREL', 'menestrel', 'Description Ménestrel', 'Le Ménestrel est un enchanteur de bataille, maniant la magie et la mélodie pour inspirer ses alliés et troubler ses ennemis. Ses chants amplifient les effets des sorts et influencent le destin en lui offrant une seconde chance sur ses actions.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/bimane#specialite:fausse-patte', 'classes/bimane', 2, 'FAUSSE PATTE', 'fausse-patte', 'Description Fausse patte', 'La Fausse Patte est un combattant agile et précis, spécialisé dans l’utilisation d’armes légères en combat double. Son style repose sur la vitesse et la fluidité, lui permettant d’enchaîner des frappes rapides sur plusieurs cibles ou de submerger un ennemi unique sous une rafale d’attaques. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/bimane#specialite:ravageur', 'classes/bimane', 1, 'RAVAGEUR', 'ravageur', 'Description Ravageur', 'Le Ravageur est un maître du combat à deux armes lourdes, combinant puissance et technique pour écraser ses adversaires. Contrairement aux autres guerriers, il réduit les malus liés à l’ambidextrie, rendant ses frappes plus fluides et dévastatrices. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/clerc#specialite:saint-combattant', 'classes/clerc', 1, 'SAINT COMBATTANT', 'saint-combattant', 'Description Saint combattant', 'Le Saint Combattant est à la fois un combattant et un guérisseur, portant les idéaux de son dieu sur le champ de bataille. Son corps endure les souffrances du combat tandis que sa foi lui permet d’apporter soin et protection à ses alliés.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/clerc#specialite:zelote', 'classes/clerc', 2, 'ZÉLOTE', 'zelote', 'Description Zélote', 'Le Zélote est le bras armé de sa divinité, un fervent serviteur qui impose la volonté divine par le chakra et l''acier. Il combat avec une ferveur inébranlable, punissant les impies et purifiant le monde des forces impures.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/cuirasse#specialite:protecteur', 'classes/cuirasse', 2, 'PROTECTEUR', 'protecteur', 'Description Protecteur', 'Le Protecteur est l’incarnation du rempart absolu, un bouclier vivant qui se dresse entre ses alliés et le danger. Maîtrisant l’art de la parade et l’utilisation des boucliers comme armes, il neutralise les assauts ennemis avec une précision inébranlable. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/cuirasse#specialite:vindicatif', 'classes/cuirasse', 1, 'VINDICATIF', 'vindicatif', 'Description Vindicatif', 'Le Vindicatif est un guerrier de fer animé par la rage et la détermination. Abandonnant la pure défense, il utilise son armure lourde pour foncer dans la mêlée et punir ses ennemis avec une force implacable. Son sens de la justice ou de la vengeance guide ses frappes, lui offrant des avantages contre certaines cibles. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/fenrir#specialite:belliciste', 'classes/fenrir', 1, 'BELLICISTE', 'belliciste', 'Description Belliciste', 'Le Belliciste est un combattant féroce, dominant ses ennemis par sa maîtrise des lames et son aura d’alpha. Ses armes tranchantes sont imprégnées d’une sauvagerie instinctive, augmentant les chances d’infliger des saignements à ses adversaires.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/fenrir#specialite:gourou', 'classes/fenrir', 2, 'GOUROU', 'gourou', 'Description Gourou', 'Le Gourou est un fenrir spirituel, puisant sa puissance dans les éléments de Glace, Ombre et Foudre avec aisance. Son lien avec la lune lui confère une résistance accrue aux forces du soleil.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/flagelleur#specialite:masochiste', 'classes/flagelleur', 2, 'MASOCHISTE', 'masochiste', 'Description Masochiste', 'Le Masochiste ne cherche ni la gloire ni la victoire rapide. Pour lui, chaque blessure est une leçon, chaque altération un test à réussir. Là où d’autres reculent face à la douleur, il avance, par une volonté de fer, insensible aux afflictions qui briseraient des combattants plus ordinaires.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/flagelleur#specialite:sadique', 'classes/flagelleur', 1, 'SADIQUE', 'sadique', 'Description Sadique', 'Le Sadique ne combat pas pour vaincre rapidement, mais pour voir ses ennemis souffrir lentement. Chaque altération d’état infligée prolonge son emprise sur ses victimes, les affaiblissant jusqu’à briser leur volonté.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/frappeur#specialite:briseur', 'classes/frappeur', 2, 'BRISEUR', 'briseur', 'Description Briseur', 'Le Briseur est une force destructrice incarnée, spécialisé dans l’annihilation des défenses ennemies. Qu’il s’agisse d’armures, d’armes ou même de l''intégrité de son adversaire, tout cède sous l’impact de ses assauts brutaux. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/frappeur#specialite:casseur', 'classes/frappeur', 1, 'CASSEUR', 'casseur', 'Description Casseur', 'Le Casseur est un spécialiste de la destruction des postures de combat, brisant l’équilibre et la concentration de ses adversaires avec des frappes calculées. Il ne se contente pas d’infliger des dégâts : chaque coup casse la posture de l''adversaire, le rendant totalement vulnérable contre d''autres ennemis potentiels.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/goleois#specialite:irreductible', 'classes/goleois', 1, 'IRRÉDUCTIBLE', 'irreductible', 'Description Irréductible', NULL, 'classes', 'Classe Maverick V7 › Goleois › A17:M19, AM17:BA17', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/goleois#specialite:saronide', 'classes/goleois', 2, 'SARONIDE', 'saronide', 'Description Saronide', NULL, 'classes', 'Classe Maverick V7 › Goleois › X17:AJ19, AM31:BA31', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/grenadier#specialite:artilleur', 'classes/grenadier', 1, 'ARTILLEUR', 'artilleur', NULL, NULL, 'classes', 'Classe Maverick V7 › Grenadier › A17:M19', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/grenadier#specialite:bombardier', 'classes/grenadier', 2, 'BOMBARDIER', 'bombardier', NULL, NULL, 'classes', 'Classe Maverick V7 › Grenadier › X17:AJ19', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/guerrier#specialite:epeiste', 'classes/guerrier', 1, 'ÉPÉISTE', 'epeiste', 'Description Épéiste', 'L''Épéiste est un maître des lames, ayant abandonné la hache pour perfectionner son art du combat rapide et précis. Grâce à son entraînement rigoureux, il manie épées et dagues avec une habileté mortelle.. Face à un adversaire unique, il excelle dans son domaine.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/guerrier#specialite:maitre-darme', 'classes/guerrier', 2, 'MAÎTRE D''ARME', 'maitre-darme', 'Description Maître d''arme', 'Le Maître d''Arme est un guerrier polyvalent, rompu à l’art du combat avec beaucoup d’armes différentes. Son expertise lui permet d’adapter son style en fonction de la situation, maniant aussi bien les armes légères que lourdes avec une efficacité redoutable. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/jackalope#specialite:adepte', 'classes/jackalope', 2, 'ADEPTE', 'adepte', 'Description Adepte', 'L’Adepte est un érudit du combat, puisant dans les flux de la Terre, du Foudre et du Vide pour équilibrer sa puissance et ses connaissances.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/jackalope#specialite:ninja', 'classes/jackalope', 1, 'NINJA', 'ninja', 'Description Ninja', 'Le Ninja est un jackalope furtif et calculateur, maniant aussi bien les armes légères que lourdes avec une forte précision. Il maîtrise l’art de la défense, transformant chaque attaque manquée en une occasion de frapper.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/kitsune#specialite:druide', 'classes/kitsune', 2, 'DRUIDE', 'druide', 'Description Druide', 'Le Druide puise son pouvoir au plus profond de sa magie, manipulant le Feu, la Lumière ou le Vent avec aisance. Protecteur et guérisseur, il allège les souffrances tout en réduisant le coût de ses sorts élémentaires.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/kitsune#specialite:fripon', 'classes/kitsune', 1, 'FRIPON', 'fripon', 'Description Fripon', 'Le Fripon ne combat pas à la loyale, et c’est ce qui fait sa force. Il frappe par surprise, s’éclipse en un clin d’œil et manipule le destin à son avantage. Chaque attaque discrète qu’il porte est plus efficace qu’elle n’y paraît.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/lanceur#specialite:fantassin', 'classes/lanceur', 1, 'FANTASSIN', 'fantassin', 'Description Fantassin', 'Le Fantassin est un guerrier polyvalent combinant armes de jet et combat rapproché avec une efficacité redoutable. Capable de  porter une armure intermédiaire, il est parfaitement capable d''encaisser des coups si l''ennemi se rapproche trop.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/lanceur#specialite:jongleur', 'classes/lanceur', 2, 'JONGLEUR', 'jongleur', 'Description Jongleur', 'Le Jongleur est un maître de l’agilité et du lancer, combinant spectacle et efficacité martiale. Spécialiste des armes légères, il enchaîne ses attaques avec fluidité et précision, frappant ses cibles avec une rapidité déconcertante.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/lancier#specialite:maitre-dhast', 'classes/lancier', 1, 'MAÎTRE D''HAST', 'maitre-dhast', 'Description Maître d''hast', 'Le Maître d’Hast est un combattant d’élite, combinant la puissance de l’armure lourde avec la portée et la précision des armes d’hast. Qu’il combatte à pied ou à dos de monture, il tire parti de sa stabilité et de son athlétisme pour dominer le champ de bataille. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/lancier#specialite:myrmidon', 'classes/lancier', 2, 'MYRMIDON', 'myrmidon', 'Description Myrmidon', 'Le Myrmidon est un guerrier versatile. Grâce à son entraînement physique poussé, il se déplace avec fluidité sur le champ de bataille, bondissant sur ses ennemis pour des frappes précises et puissantes. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/maclier#specialite:archiclier', 'classes/maclier', 1, 'ARCHICLIER', 'archiclier', 'Description Archiclier', 'L’Archiclier est un maître de la défense absolue, capable d’encaisser et de détourner aussi bien les attaques physiques que magiques. Grâce à son bouclier imprégné de magie, il annule les assauts les plus puissants.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/maclier#specialite:grand-maclier', 'classes/maclier', 2, 'GRAND MACLIER', 'grand-maclier', 'Description Grand maclier', 'Le Grand Maclier est un protecteur légendaire, maniant son bouclier comme personne. Capable de frapper plusieurs adversaires ou de bénir ses alliés.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/mage#specialite:mage-blanc', 'classes/mage', 2, 'MAGE BLANC', 'mage-blanc', 'Description Mage blanc', 'Le Mage Blanc est un maître de la guérison et de la protection, utilisant sa magie pour soigner et renforcer ses alliés. Son pouvoir lui permet de transformer ses sorts offensifs en soins, assurant le soutien pour le groupe en toute situation.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/mage#specialite:mage-noir', 'classes/mage', 1, 'MAGE NOIR', 'mage-noir', 'Description Mage noir', 'Le Mage Noir est un destructeur né, spécialisé dans les sorts offensifs et les altérations d’état. Sa magie brute lui permet d’infliger de lourds dégâts tout en affaiblissant ses adversaires sur la durée.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/mage-bleu#specialite:dresseur-bleu', 'classes/mage-bleu', 2, 'DRESSEUR BLEU', 'dresseur-bleu', 'Description Dresseur bleu', NULL, 'classes', 'Classe Maverick V7 › Mage Bleu › X17:AJ19, AM31:BA31', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/mage-bleu#specialite:mage-saphir', 'classes/mage-bleu', 1, 'MAGE SAPHIR', 'mage-saphir', 'Description Mage saphir', NULL, 'classes', 'Classe Maverick V7 › Mage Bleu › A17:M19, AM17:BA17', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/mage-rouge#specialite:mage-grenat', 'classes/mage-rouge', 2, 'MAGE GRENAT', 'mage-grenat', 'Description Mage grenat', 'Contrairement aux autres mages, le Mage Grenat ne se repose pas uniquement sur ses sorts, mais sur son arme qu’il transforme en canal de puissance. Chaque coup qu’il porte est imprégné de volonté, frappant avec une force supérieure contrairement aux autres mages.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/mage-rouge#specialite:mage-rubis', 'classes/mage-rouge', 1, 'MAGE RUBIS', 'mage-rubis', 'Description Mage rubis', 'Le Mage Rubis repousse les limites de la puissance magique en concentrant son énergie pour frapper plus fort que n’importe quel autre mage de mêlée. Chaque sort qu’il lance, qu’il soit préparé ou instantané, gagne en intensité, écrasant les adversaires.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/mage-vert#specialite:mage-emeraude', 'classes/mage-vert', 1, 'MAGE ÉMERAUDE', 'mage-emeraude', 'Description Mage émeraude', 'Le Mage Émeraude ne se contente pas de tirer, il perfectionne chaque coup en exploitant la posture Focus. Maître de son arme et de sa volonté, il canalise son énergie pour transformer chaque projectile en un tir quasi imparable.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/mage-vert#specialite:mage-jade', 'classes/mage-vert', 2, 'MAGE JADE', 'mage-jade', 'Description Mage jade', 'Le Mage Jade ne se contente pas d’enchanter ses projectiles, il fusionne complètement son arme et sa magie grâce à la posture Symbiose. Ses tirs deviennent une extension de son Chakra, perçant les défenses et ignorant les restrictions classiques de munitions.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/marcass#specialite:canaille', 'classes/marcass', 1, 'CANAILLE', 'canaille', 'Description Canaille', 'La Canaille est un marcass rustre qui transforme son propre corps et son environnement en armes de fortune. Maître de l’adaptation, il exploite sa force brutale pour maximiser l’impact de ses attaques.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/marcass#specialite:devot', 'classes/marcass', 2, 'DÉVOT', 'devot', 'Description Dévot', 'Le Dévot est un mage singulier, fusionnant sa foi et sa magie pour créer un lien profond avec les éléments et les forces mystiques. Son pouvoir dépend fortement de son apparence et des couleurs qu’il porte, lui conférant des bonus spécifiques en fonction de son affinité avec le Feu, la Terre ou la Nécromancie.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/martiale#specialite:berserker', 'classes/martiale', 2, 'BERSERKER', 'berserker', 'Description Berserker', 'Le Berserker est un combattant sauvage qui canalise sa rage en une force destructrice inarrêtable. Contrairement aux autres guerriers, il peut prolonger son état de fureur par pure volonté, maintenant un état de combat frénétique plus longtemps. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/martiale#specialite:heros', 'classes/martiale', 1, 'HÉROS', 'heros', 'Description Héros', 'Le Héros est un combattant unique, capable de modifier sa posture à volonté pendant son tour, une flexibilité qu’aucune autre classe ne possède. Grâce à cette maîtrise, il s’adapte instantanément aux exigences du combat.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/medusain#specialite:augure', 'classes/medusain', 2, 'AUGURE', 'augure', 'Description Augure', 'L’Augure est un médusain mystique dont la vision s’étend bien au-delà de la réalité. Doté d’une perception à 360° comme la classe Pape, il anticipe les menaces avant même qu’elles ne surgissent, manipulant les magies de l’Eau, de la Foudre ou de l''Ombre pour se défendre.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/medusain#specialite:hoplite', 'classes/medusain', 1, 'HOPLITE', 'hoplite', 'Description Hoplite', 'L’Hoplite est un médusain discipliné, spécialiste des armes d’estoc et des techniques défensives. Son style de combat repose sur des frappes précises et une défense inébranlable, exploitant la puissance de son épaisse {{barriere|barrière}} pour encaisser les assauts les plus brutaux.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/mercenaire#specialite:chasseur-de-primes', 'classes/mercenaire', 2, 'CHASSEUR DE PRIMES', 'chasseur-de-primes', 'Description Chasseur de Primes', 'Le Chasseur de Primes est un traqueur aguerri, expert en pistage et en négociation. Toujours en quête de la meilleure récompense, il sait maximiser ses profits en revendant au meilleur prix et en tirant parti de chaque contrat. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/mercenaire#specialite:combattant-libre', 'classes/mercenaire', 1, 'COMBATTANT LIBRE', 'combattant-libre', 'Description Combattant Libre', 'Le Combattant Libre est un combattant sans attaches ni règles, s’adaptant à chaque combat avec ingéniosité et opportunisme. Capable de manier une grande variété d’armes et d’armures, il a la capacité unique de pouvoir imiter les réussites de ses adversaires pour pouvoir les retourner contre eux.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/minotaure#specialite:gladiateur', 'classes/minotaure', 1, 'GLADIATEUR', 'gladiateur', 'Description Gladiateur', 'Le Gladiateur incarne la force brute et l’instinct du combat, maîtrisant aussi bien les armes lourdes que l’arc géant de guerre. Dans l’arène ou sur le champ de bataille, il domine par sa présence imposante et son aptitude à briser les défenses adverses.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/minotaure#specialite:medium', 'classes/minotaure', 2, 'MÉDIUM', 'medium', 'Description Médium', 'Le Médium est un minotaure des forces occultes, puisant sa puissance dans le Sang, l’Ombre ou la Terre. Il canalise ces énergies pour garder les châtiments plus longtemps ou faire saigner ses adversaires.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/moine#specialite:moine-guerrier', 'classes/moine', 1, 'MOINE GUERRIER', 'moine-guerrier', 'Description Moine guerrier', 'Le Moine Guerrier est un combattant ascétique maîtrisant à la fois l’art du combat et celui de la médecine. Armé de sa force et de sa foi, il frappe avec précision tout en étant capable de soigner ses alliés au cœur de la bataille. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/moine#specialite:templier', 'classes/moine', 2, 'TEMPLIER', 'templier', 'Description Templier', 'Le Templier est un guerrier sacré, un rempart vivant dédié à l’ordre et à la justice. Protégé par son armure lourde et sa foi inébranlable, il traque les hérétiques et les ennemis de sa divinité avec une détermination inébranlable. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/namazu#specialite:batailleur', 'classes/namazu', 1, 'BATAILLEUR', 'batailleur', 'Description Batailleur', 'Le Batailleur ne recule devant aucun affrontement, utilisant sa force brute et ses instincts de chasseur pour dominer ses adversaires.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/namazu#specialite:devin', 'classes/namazu', 2, 'DEVIN', 'devin', 'Description Devin', 'Le Devin est un mage namazu dont le pouvoir fluctue comme l’océan, alternant entre apaisement et destruction. Son lien profond avec l’Eau, le Sang ou l’Ombre lui permet d’adapter sa magie aux conditions environnantes, tirant profit de la pluie et des marées.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/ocultomancien#specialite:meteorologue', 'classes/ocultomancien', 2, 'MÉTÉOROLOGUE', 'meteorologue', 'Description Météorologue', 'Le Météorologue manipule le climat à son avantage, transformant la météo en un outil stratégique redoutable. Qu’il amplifie les effets du temps ou neutralise ses malus, il dicte à quelle sauce vont être mangés ses adversaires.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/ocultomancien#specialite:specialiste', 'classes/ocultomancien', 1, 'SPÉCIALISTE', 'specialiste', 'Description Spécialiste', 'Loin de la polyvalence des autres mages, le Spécialiste pousse l’art de sa propre magie à son paroxysme. Il perfectionne chaque sort, amplifiant ses dégâts ou renforçant ses défenses contre son propre élément.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/olwman#specialite:chasseur', 'classes/olwman', 1, 'CHASSEUR', 'chasseur', 'Description Chasseur', 'Le Chasseur est un expert de la traque, capable de repérer et d’abattre sa proie avec une efficacité implacable. Grâce à sa précision nocturne, il devient encore plus redoutable sous le couvert des ténèbres, frappant ses cibles là où elles sont les plus vulnérables.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/olwman#specialite:pape', 'classes/olwman', 2, 'PAPE', 'pape', 'Description Pape', 'Le Pape est un olwman sage dont la perception dépasse celle des mortels. Sa vision à 360° ou sa clairvoyance lui permettent d’anticiper les dangers et d’atteindre les esprits intangibles.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/orios#specialite:chaman', 'classes/orios', 2, 'CHAMAN', 'chaman', 'Description Chaman', 'Le Chaman est un orios mystique, en harmonie avec les forces qui constituent les orios. Il puise dans l’énergie des forêts, de la pluie et du sang pour renforcer sa magie et celle de ses alliés.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/orios#specialite:va-t-en-guerre', 'classes/orios', 1, 'VA-T-EN-GUERRE', 'va-t-en-guerre', 'Description Va-t-en-guerre', 'Le Va-t-en-guerre est un colosse de combat, un guerrier taillé pour l’affrontement direct et l’usage d’armes démesurées. Son style repose sur une force brute incomparable, montrant toute la supériorité des Orios sur le plan de la force.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/parleur#specialite:bonimenteur', 'classes/parleur', 1, 'BONIMENTEUR', 'bonimenteur', 'Description Bonimenteur', 'Le Bonimenteur est un maître du mauvais verbe, utilisant son charisme et sa ruse pour manipuler son entourage. Expert en négociation et en supercherie, il sait convaincre, duper et détourner l’attention pour parvenir à ses fins. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/parleur#specialite:eloquent', 'classes/parleur', 2, 'ÉLOQUENT', 'eloquent', 'Description Éloquent', 'L’Éloquent est un orateur hors pair, capable d’influencer son entourage par la simple force de ses mots. Diplomate habile ou maître de l’intimidation, chaque mot est une arme redoutable, capable de manipuler les émotions et les intentions de ses adversaires. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/pugiliste#specialite:cogneur', 'classes/pugiliste', 1, 'COGNEUR', 'cogneur', 'Description Cogneur', 'Le Cogneur est un combattant imposant, combinant puissance brute et résistance inébranlable. Spécialisé dans le combat à mains nues, il frappe avec une force qui fait vaciller même les plus grands adversaires. Son endurance hors norme lui permet d’encaisser les coups sans faiblir et de rester infatigable en plein affrontement. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/pugiliste#specialite:lutteur', 'classes/pugiliste', 2, 'LUTTEUR', 'lutteur', 'Description Lutteur', 'Le Lutteur est un guerrier du corps à corps, maîtrisant l’art des projections et des prises. Son style repose sur sa force physique et sa capacité à encaisser les coups tout en infligeant des dégâts accrus à ses adversaires. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/rokh#specialite:colombe', 'classes/rokh', 2, 'COLOMBE', 'colombe', 'Description Colombe', 'La Colombe est un rokh qui incarne la rapidité, la magie et la clairvoyance céleste. Maître du Vent, de la Foudre ou de la Lumière, elle réduit le coût de ses sorts et se déplace avec une aisance inégalée dans les airs.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/rokh#specialite:hirondelle', 'classes/rokh', 1, 'HIRONDELLE', 'hirondelle', 'Description Hirondelle', 'L''Hirondelle est un combattant aérien d''une rapidité fulgurante, frappant avant que l''ennemi ne puisse réagir. Sa capacité unique à utiliser ses plumes comme armes fait de lui un archer naturel, toujours prêt à décocher des projectiles en plein vol.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/satyre#specialite:galopin', 'classes/satyre', 1, 'GALOPIN', 'galopin', 'Description Galopin', 'Le Galopin ne combat pas à la force brute, mais à l’art de la persuasion et du contrôle. Son talent pour endormir, enchevêtrer ou influencer ses adversaires en fait un maître du jeu mental sur le champ de bataille.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/satyre#specialite:oracle', 'classes/satyre', 2, 'ORACLE', 'oracle', 'Description Oracle', 'L’Oracle est un satyre troublant, oscillant entre sagesse et provocation, jouant avec l’esprit et les éléments. Son influence psychologique est telle qu’il peut manipuler le langage de ceux qui l’entourent, les plongeant dans une confusion inexplicable.
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/tueur#specialite:fletrisseur', 'classes/tueur', 1, 'FLÉTRISSEUR', 'fletrisseur', 'Description Flétrisseur', NULL, 'classes', 'Classe Maverick V7 › Tueur › A17:M19, AM17:BA17', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/tueur#specialite:sicaire', 'classes/tueur', 2, 'SICAIRE', 'sicaire', 'Description Sicaire', NULL, 'classes', 'Classe Maverick V7 › Tueur › X17:AJ19, AM31:BA31', NULL);
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/voleur#specialite:cambrioleur', 'classes/voleur', 1, 'CAMBRIOLEUR', 'cambrioleur', 'Description Cambrioleur', 'Le Cambrioleur est un maître de l’infiltration et du vol, se faufilant partout sans laisser de traces. Grâce à sa ruse, il évite les attaques opportunistes et se joue des défenses les plus solides. Expert en crochetage et en falsification, il peut ouvrir presque toutes les serrures et falsifier des documents pour arriver à ses fins. 
INSERT INTO specialite (id, classe_id, rang, nom, nom_cle, description_titre, description, origine, source_ref, remarque) VALUES ('classes/voleur#specialite:saboteur', 'classes/voleur', 2, 'SABOTEUR', 'saboteur', 'Description Saboteur', 'Le Saboteur est un maître des pièges et des explosifs, transformant le champ de bataille en un terrain mortel pour ses ennemis. Grâce à sa maîtrise du sabotage, il pose discrètement de redoutables pièges capables de renverser un combat en un instant. 
